import static thaumcraft.test.ExchangeProbe.check;

@Mod.EventBusSubscriber(modid="thaumcraft")
public final class ContainerFocusProbe {
 public static final BlockPos P=new BlockPos(8,180,8),Q=P.above(),SAVE=P.east(8);
 static ServerPlayer actor;static ItemStack caster;static BlockPos deniedBreak,deniedPlace;static boolean inspectFilled;static int ticks,stage;static long due;static BlockEntity original;static boolean done;static float balance;
 static String mode(){return System.getProperty("thaumcraft.containerFocusProbe","");}
 public static ItemStack treasure(){var s=new ItemStack(Items.DIAMOND,13);s.set(DataComponents.CUSTOM_NAME,Component.literal("Container 76: preserve me"));var tag=new CompoundTag();tag.putString("stamp","unique-container-76");s.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));return s;}
 public static FocusProgram.Effect effect(String kind){return new FocusProgram.Effect(kind,1,1);}
 static void name(BlockEntity entity,String value){var item=new ItemStack(entity.getBlockState().getBlock());item.set(DataComponents.CUSTOM_NAME,Component.literal(value));if(entity instanceof Container container){var slots=new ArrayList<ItemStack>();for(int i=0;i<container.getContainerSize();i++)slots.add(container.getItem(i).copy());item.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(slots));}entity.applyComponentsFromItemStack(item);}
 static ItemStack filledBox(){var box=new ItemStack(Items.DYED_SHULKER_BOX.red());box.set(DataComponents.CUSTOM_NAME,Component.literal("Packed 76"));box.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(treasure())));return box;}
 static int inside(ItemStack s){return (ItemStack.isSameItemSameComponents(s,treasure())?s.getCount():0)+s.getOrDefault(DataComponents.CONTAINER,ItemContainerContents.EMPTY).nonEmptyItemCopyStream().mapToInt(ContainerFocusProbe::inside).sum();}
 static List<ItemStack> all(ServerLevel l){var items=new ArrayList<ItemStack>();if(actor!=null)for(int i=0;i<actor.getInventory().getContainerSize();i++)items.add(actor.getInventory().getItem(i));for(var e:l.getEntitiesOfClass(ItemEntity.class,new AABB(P).inflate(40)))items.add(e.getItem());return items;}
 static int treasureCount(ServerLevel l){return all(l).stream().mapToInt(ContainerFocusProbe::inside).sum();}
 static int count(ServerLevel l,Item item){return all(l).stream().filter(s->s.is(item)).mapToInt(ItemStack::getCount).sum();}
 static ItemStack find(ServerLevel l,Item item){return all(l).stream().filter(s->s.is(item)).findFirst().orElse(ItemStack.EMPTY);}
 static float vis(ServerLevel l){return AuraManager.get(l,Q).vis();}
 static void reset(ServerLevel l){for(int x=-2;x<=2;x++)for(int y=0;y<=2;y++)for(int z=-2;z<=2;z++)l.setBlock(P.offset(x,y,z),Blocks.AIR.defaultBlockState(),Block.UPDATE_SKIP_ALL_SIDEEFFECTS|Block.UPDATE_CLIENTS);for(var e:l.getEntitiesOfClass(ItemEntity.class,new AABB(P).inflate(40)))e.discard();actor.closeContainer();actor.getInventory().clearContent();actor.setGameMode(GameType.SURVIVAL);caster=ExchangeProbe.equip(actor,new FocusProgram("bolt",List.of(effect("exchange"))));caster.set(ThaumaturgyContent.PICKED_BLOCK.get(),new ItemStack(Items.DIRT));actor.getInventory().setItem(10,new ItemStack(Items.DIRT,4));actor.setPos(8.5,180,5.5);AuraManager.addVis(l,Q,1000);deniedBreak=deniedPlace=null;inspectFilled=false;}
 static ChestBlockEntity chest(ServerLevel l,BlockPos q){l.setBlockAndUpdate(q,Blocks.CHEST.defaultBlockState());var c=(ChestBlockEntity)l.getBlockEntity(q);name(c,"Guarded 76");c.setItem(0,treasure());return c;}
 static boolean exchange(ServerLevel l){return FocusExchange.exchange(actor,new BlockHitResult(Vec3.atCenterOf(Q),Direction.UP,Q,false),effect("exchange"));}
 static void mine(ServerLevel l,BlockPos q){SpellEngine.apply(actor,new FocusProgram("bolt",List.of(effect("break"))),new BlockHitResult(Vec3.atCenterOf(q),Direction.UP,q,false));}
 @SubscribeEvent public static void denyBreak(net.minecraftforge.event.level.BlockEvent.BreakEvent e){if(!mode().isEmpty()&&e.getPos().equals(deniedBreak))e.setResult(net.minecraftforge.common.util.Result.DENY);}
 @SubscribeEvent public static boolean denyPlace(net.minecraftforge.event.level.BlockEvent.EntityPlaceEvent e){if(mode().isEmpty()||!e.getPos().equals(deniedPlace))return false;if(inspectFilled){check(e.getLevel().getBlockEntity(Q) instanceof ShulkerBoxBlockEntity,"Place event lacks real destination entity");var box=(ShulkerBoxBlockEntity)e.getLevel().getBlockEntity(Q);check(ItemStack.matches(box.getItem(0),treasure()),"Place event lacks intended contents");}return true;}
 static void exchangeTests(ServerLevel l){reset(l);var c=chest(l,Q);actor.openMenu(c);var nbt=c.saveWithoutMetadata(l.registryAccess());balance=vis(l);deniedPlace=Q;check(!exchange(l),"Denied chest exchange succeeded");check(l.getBlockEntity(Q)==c&&c.saveWithoutMetadata(l.registryAccess()).equals(nbt)&&vis(l)==balance&&actor.getInventory().getItem(10).getCount()==4&&treasureCount(l)==0,"Denied placement changed source, cost or loot");check(c.getCapability(net.minecraftforge.common.capabilities.ForgeCapabilities.ITEM_HANDLER,Direction.UP).isPresent(),"Rollback did not revive inventory capability");check(actor.containerMenu.getSlot(0).getItem().getCount()==13,"Open menu no longer references original inventory");deniedPlace=null;deniedBreak=Q;check(!exchange(l)&&l.getBlockEntity(Q)==c&&c.saveWithoutMetadata(l.registryAccess()).equals(nbt)&&treasureCount(l)==0,"Break denial changed container");deniedBreak=null;actor.closeContainer();check(exchange(l)&&l.getBlockState(Q).is(Blocks.DIRT)&&treasureCount(l)==13&&count(l,Items.CHEST)==1&&Math.abs(vis(l)-(balance-.25F))<.001,"Chest exchange lost/duplicated content or cost");check(find(l,Items.CHEST).getHoverName().getString().equals("Guarded 76"),"Chest name lost");
  reset(l);l.setBlockAndUpdate(Q,Blocks.CHEST.defaultBlockState().setValue(ChestBlock.TYPE,ChestType.LEFT));l.setBlockAndUpdate(Q.east(),Blocks.CHEST.defaultBlockState().setValue(ChestBlock.TYPE,ChestType.RIGHT));var left=(ChestBlockEntity)l.getBlockEntity(Q);var right=(ChestBlockEntity)l.getBlockEntity(Q.east());left.setItem(0,treasure());right.setItem(0,new ItemStack(Items.EMERALD,17));check(exchange(l)&&treasureCount(l)==13&&l.getBlockEntity(Q.east())==right&&right.getItem(0).getCount()==17&&right.getBlockState().getValue(ChestBlock.TYPE)==ChestType.SINGLE,"Double chest spilled both halves or lost remaining inventory");
  reset(l);l.setBlockAndUpdate(Q,Blocks.DYED_SHULKER_BOX.red().defaultBlockState());var box=(ShulkerBoxBlockEntity)l.getBlockEntity(Q);box.setItem(0,treasure());name(box,"Packed 76");check(exchange(l)&&treasureCount(l)==13&&count(l,Items.DYED_SHULKER_BOX.red())==1&&inside(find(l,Items.DYED_SHULKER_BOX.red()))==13,"Portable box lost/duplicated contents");check(all(l).stream().filter(s->s.is(Items.DIAMOND)).mapToInt(ItemStack::getCount).sum()==0,"Shulker also spilled contents loose");
  reset(l);l.setBlockAndUpdate(Q,Blocks.STONE.defaultBlockState());caster.set(ThaumaturgyContent.PICKED_BLOCK.get(),new ItemStack(Items.DYED_SHULKER_BOX.red()));var payment=filledBox();actor.getInventory().setItem(10,payment);deniedPlace=Q;inspectFilled=true;balance=vis(l);check(!exchange(l)&&l.getBlockState(Q).is(Blocks.STONE)&&l.getBlockEntity(Q)==null&&ItemStack.matches(payment,filledBox())&&treasureCount(l)==13&&vis(l)==balance,"Denied filled destination consumed/duplicated item or left ghost entity");deniedPlace=null;inspectFilled=false;check(exchange(l)&&payment.isEmpty()&&l.getBlockEntity(Q) instanceof ShulkerBoxBlockEntity,"Filled destination not placed");box=(ShulkerBoxBlockEntity)l.getBlockEntity(Q);check(ItemStack.matches(box.getItem(0),treasure())&&box.getCustomName().getString().equals("Packed 76"),"Destination contents or name lost");
  actor.setShiftKeyDown(true);check(ExchangeSelection.pick(actor,caster,Q),"Could not sample full box");actor.setShiftKeyDown(false);check(inside(ExchangeSelection.selected(caster))==0&&ItemStack.matches(box.getItem(0),treasure()),"Sampling cloned or removed contents");
  reset(l);l.setBlockAndUpdate(Q,Blocks.STONE.defaultBlockState());caster.remove(ThaumaturgyContent.PICKED_BLOCK.get());var otherBox=filledBox();actor.getInventory().setItem(9,otherBox);var offBox=filledBox();offBox.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(treasure().copyWithCount(7))));actor.setItemInHand(InteractionHand.OFF_HAND,offBox);check(exchange(l)&&actor.getOffhandItem().isEmpty()&&ItemStack.matches(otherBox,filledBox())&&((ShulkerBoxBlockEntity)l.getBlockEntity(Q)).getItem(0).getCount()==7,"Offhand fallback consumed a different filled box");
  reset(l);l.setBlockAndUpdate(Q,Blocks.STONE.defaultBlockState());caster.remove(ThaumaturgyContent.PICKED_BLOCK.get());otherBox=filledBox();actor.getInventory().setItem(9,otherBox);actor.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.DYED_SHULKER_BOX.red()));check(exchange(l)&&actor.getOffhandItem().isEmpty()&&ItemStack.matches(otherBox,filledBox())&&((ShulkerBoxBlockEntity)l.getBlockEntity(Q)).isEmpty(),"Empty offhand sample consumed a filled box instead");
  reset(l);l.setBlockAndUpdate(Q,thaumcraft.storage.HungryChest.BLOCK.get().defaultBlockState());((ChestBlockEntity)l.getBlockEntity(Q)).setItem(0,treasure());check(exchange(l)&&treasureCount(l)==13&&count(l,thaumcraft.storage.HungryChest.BLOCK.get().asItem())==1,"Hungry chest not harvested natively");
  reset(l);var jarItem=thaumcraft.alchemy.AlchemyContent.filled(thaumcraft.alchemy.AlchemyContent.JAR.get().asItem(),"aer",64);caster.set(ThaumaturgyContent.PICKED_BLOCK.get(),new ItemStack(jarItem.getItem()));actor.getInventory().setItem(10,jarItem);l.setBlockAndUpdate(Q,Blocks.STONE.defaultBlockState());check(exchange(l)&&l.getBlockEntity(Q) instanceof thaumcraft.alchemy.AlchemyMachine,"Jar not placed");var jar=(thaumcraft.alchemy.AlchemyMachine)l.getBlockEntity(Q);check(jar.total()==64,"Jar essence not placed from actual item");caster.set(ThaumaturgyContent.PICKED_BLOCK.get(),new ItemStack(Items.DIRT));actor.getInventory().setItem(10,new ItemStack(Items.DIRT,4));check(exchange(l)&&thaumcraft.alchemy.AlchemyContent.amount(find(l,thaumcraft.alchemy.AlchemyContent.JAR.get().asItem()))==64,"Jar essence lost during removal");
  reset(l);c=chest(l,Q);for(int i=0;i<36;i++)if(i!=actor.getInventory().getSelectedSlot())actor.getInventory().setItem(i,new ItemStack(Items.STONE,64));actor.getInventory().setItem(10,new ItemStack(Items.DIRT,4));check(exchange(l)&&treasureCount(l)==13&&count(l,Items.CHEST)==1,"Full inventory lost overflow");
  reset(l);l.setBlockAndUpdate(Q,Blocks.DYED_SHULKER_BOX.red().defaultBlockState());box=(ShulkerBoxBlockEntity)l.getBlockEntity(Q);box.setItem(0,treasure());actor.setGameMode(GameType.CREATIVE);balance=vis(l);check(exchange(l)&&treasureCount(l)==13&&count(l,Items.DYED_SHULKER_BOX.red())==1&&vis(l)==balance,"Creative exchange erased portable contents");
  reset(l);l.setBlockAndUpdate(Q,thaumcraft.infusion.InfusionContent.ARCANE.get().defaultBlockState());var pedestal=(thaumcraft.infusion.InfusionPedestal)l.getBlockEntity(Q);var raw=pedestal.saveWithoutMetadata(l.registryAccess());var future=new CompoundTag();future.putInt("version",99);future.putString("payload","preserve unknown offering");raw.put("offering",future);pedestal.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),raw));check(!pedestal.supported()&&!exchange(l)&&!FocusBreaking.start(actor,Q,Direction.UP,effect("break"),1,0)&&l.getBlockEntity(Q)==pedestal&&pedestal.saveWithoutMetadata(l.registryAccess()).equals(raw),"Unknown data was destructively harvested");
  thaumcraft.Thaumcraft.LOGGER.info("CONTAINER76_EXCHANGE_OK: rollback identity/NBT/capability/menu, double chest, shulker round trip, no sample cloning, hungry chest, jar essence, overflow, creative and future data");
 }
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(done||!List.of("write","read").contains(mode())||++ticks<40)return;var l=e.server().overworld();long now=l.getGameTime();
  if(actor==null){l.setChunkForced(0,0,true);l.getChunkAt(P);l.getChunkAt(SAVE);actor=ExchangeProbe.player(l,"Container76");if(mode().equals("read")){var save=(ChestBlockEntity)l.getBlockEntity(SAVE);check(save!=null,"Save missing");caster=save.getItem(0).copy();check(ExchangeSelection.selected(caster).is(Items.DYED_SHULKER_BOX.red()),"Container sample did not persist");var packed=save.getItem(1).copy();check(inside(packed)==13&&packed.getHoverName().getString().equals("Packed 76"),"Packed item did not survive restart");reset(l);caster.set(ThaumaturgyContent.PICKED_BLOCK.get(),new ItemStack(Items.DYED_SHULKER_BOX.red()));actor.getInventory().setItem(10,packed);l.setBlockAndUpdate(Q,Blocks.STONE.defaultBlockState());check(exchange(l)&&ItemStack.matches(((ShulkerBoxBlockEntity)l.getBlockEntity(Q)).getItem(0),treasure()),"Restarted filled item could not be exchanged");thaumcraft.Thaumcraft.LOGGER.info("CONTAINER76_RESTART_OK: sample and portable content persist and place correctly");done=true;e.server().halt(false);return;}exchangeTests(l);reset(l);var c=chest(l,Q);balance=vis(l);mine(l,Q);check(l.getBlockEntity(Q)==c&&c.getItem(0).getCount()==13,"Rotura is not gradual");check(!FocusBreaking.start(actor,Q,Direction.UP,effect("break"),1,0),"Duplicate container mining accepted");c.setItem(0,treasure().copyWithCount(7));original=c;due=now+18;stage=1;return;}
  if(stage==1&&now>=due){check(l.isEmptyBlock(Q)&&treasureCount(l)==7&&count(l,Items.CHEST)==1,"Rotura did not use current contents exactly once");reset(l);original=chest(l,Q);var raw=original.saveWithoutMetadata(l.registryAccess());deniedBreak=Q;balance=vis(l);mine(l,Q);due=now+18;stage=2;return;}
  if(stage==2&&now>=due){check(l.getBlockEntity(Q)==original&&((ChestBlockEntity)original).getItem(0).getCount()==13&&treasureCount(l)==0,"Denied gradual mining changed inventory");reset(l);original=chest(l,Q);mine(l,Q);l.setBlock(Q,Blocks.AIR.defaultBlockState(),Block.UPDATE_SKIP_ALL_SIDEEFFECTS);var replacement=chest(l,Q);replacement.setItem(0,treasure().copyWithCount(5));original=replacement;due=now+18;stage=3;return;}
  if(stage==3&&now>=due){check(l.getBlockEntity(Q)==original&&((ChestBlockEntity)original).getItem(0).getCount()==5&&treasureCount(l)==0,"Pending work mined a replacement container");reset(l);l.setBlockAndUpdate(Q,Blocks.DYED_SHULKER_BOX.red().defaultBlockState());var box=(ShulkerBoxBlockEntity)l.getBlockEntity(Q);box.setItem(0,treasure());name(box,"Packed 76");mine(l,Q);due=now+18;stage=4;return;}
  if(stage==4&&now>=due){check(l.isEmptyBlock(Q)&&count(l,Items.DYED_SHULKER_BOX.red())==1&&treasureCount(l)==13&&inside(find(l,Items.DYED_SHULKER_BOX.red()))==13,"Rotura lost portable contents");var packed=find(l,Items.DYED_SHULKER_BOX.red()).copy();reset(l);l.setBlockAndUpdate(Q,thaumcraft.crafting.ArcaneContent.WORKBENCH.get().defaultBlockState());var table=(thaumcraft.crafting.ArcaneWorkbenchEntity)l.getBlockEntity(Q);table.inventory.setItem(0,treasure());mine(l,Q);due=now+18;stage=5;l.setBlockAndUpdate(SAVE,Blocks.CHEST.defaultBlockState());var save=(ChestBlockEntity)l.getBlockEntity(SAVE);caster.set(ThaumaturgyContent.PICKED_BLOCK.get(),new ItemStack(Items.DYED_SHULKER_BOX.red()));save.setItem(0,caster.copy());save.setItem(1,packed);return;}
  if(stage==5&&now>=due){check(l.isEmptyBlock(Q)&&treasureCount(l)==13&&count(l,thaumcraft.crafting.ArcaneContent.WORKBENCH.get().asItem())==1,"Arcane workbench inventory lost/duplicated");thaumcraft.Thaumcraft.LOGGER.info("CONTAINER76_WRITE_OK: gradual/current contents, Forge denial, entity identity, shulker portable loot and arcane inventory, saved packed item for restart");done=true;e.server().halt(false);}
 }
}
